use serde_json::Value;
fn field<'a>(v:&'a Value,a:&str,b:&str)->Option<&'a Value>{v.get(a).filter(|x|!x.is_null()).or_else(||v.get(b)).filter(|x|!x.is_null())}
fn int(v:&Value)->Option<i64>{let n=v.as_i64().or_else(||v.as_str()?.parse().ok())?;if n.unsigned_abs()<=9007199254740991{Some(n)}else{None}}
pub fn classify(v:&Value)->Option<&'static str>{if !v.is_object()||v.get("error").is_some(){return None}let p=field(v,"player_state","playerState")?;let q=field(p,"player_queue","playerQueue")?;let s=p.get("status")?;if !p.is_object()||!q.is_object()||!s.is_object(){return None}let paused=s.get("paused");if paused.is_some_and(|x|!x.is_boolean()){return None}let d=field(s,"duration_ms","durationMs");let g=field(s,"progress_ms","progressMs");if paused.is_none()&&d.is_none()&&g.is_none(){return None}for n in [d,g].into_iter().flatten(){if int(n)?<0{return None}}let list=field(q,"playable_list","playableList");if list.is_some_and(|x|!x.is_array()){return None}let i=match field(q,"current_playable_index","currentPlayableIndex"){Some(x)=>int(x)?,None=>0};if i< -1{return None}if i== -1{return Some("no_data")}let a=list?.as_array()?;if a.is_empty(){return if i==0{Some("no_data")}else{None}}let id=field(a.get(i as usize)?,"playable_id","playableId")?.as_str()?;if id.trim().is_empty(){None}else{Some("ok")}}
pub fn cooldown(frame:&Value)->Option<u64>{let err=frame.get("error")?;let mut max=0;for k in ["details","extra_headers"]{if let Some(v)=err.get(k).and_then(|x|x.get("ynison-go-away-for-seconds")){let n=int(v)?;if !(0..=315360000).contains(&n){return None}max=max.max(n as u64)}}Some(max)}
#[cfg(test)]mod tests{use super::*;#[test]fn shared_fixtures(){let a:Value=serde_json::from_str(include_str!("../../../monitor/ynison_alt/state-fixtures.json")).unwrap();for x in a.as_array().unwrap(){assert_eq!(classify(&x["frame"]),x["expected"].as_str(),"{}",x["name"]);}}#[test]fn errors(){let a=serde_json::json!({"error":{"details":{"ynison-go-away-for-seconds":"3600"},"extra_headers":{"ynison-go-away-for-seconds":1800}}});assert_eq!(cooldown(&a),Some(3600));assert_eq!(classify(&a),None);}}
